    "privacy": {
      "title": "Privacy Policy",
      "badge": "Your privacy matters to us",
      "lastUpdated": "Last updated: May 2025",
      "section1Title": "Information We Collect",
      "section1Body": "We collect minimal information to operate the App. This includes:\n\n- Bouquets you create (stored in Firebase Firestore)\n- Optional email if you submit feedback\n- Anonymous usage analytics to improve the App\n\nWe do not require you to create an account or provide personal details to use the App.",
      "section2Title": "How We Use Your Information",
      "section2Body": "We use the information we collect to:\n\n- Store and deliver your digital bouquets\n- Respond to feedback you submit\n- Improve app performance and features\n- Detect and prevent misuse",
      "section3Title": "Data Storage & Security",
      "section3Body": "Your bouquet data is stored securely in Google Firebase. We use industry-standard encryption and security practices. We retain bouquet data for 90 days after creation, after which it may be automatically deleted.",
      "section4Title": "Third-Party Services",
      "section4Body": "The App uses the following third-party services:\n\n- Google Firebase (data storage)\n- iTunes Search API (song previews - no data is sent)\n- Sarvam AI (optional AI bouquet suggestions)\n\nEach service has its own Privacy Policy governing data use.",
      "section5Title": "Cookies & Tracking",
      "section5Body": "The App does not use tracking cookies. On web, we may use local storage to remember your preferences. We do not use advertising trackers or sell your data to third parties.",
      "section6Title": "Children's Privacy",
      "section6Body": "Digi Bouquet is not directed at children under 13. We do not knowingly collect personal information from children. If you believe a child has provided us with personal information, please contact us.",
      "section7Title": "Your Rights",
      "section7Body": "You have the right to:\n\n- Access the data we hold about you\n- Request deletion of your bouquet data\n- Opt out of analytics\n\nTo exercise these rights, contact us at privacy@egreet.in.",
      "section8Title": "Changes to This Policy",
      "section8Body": "We may update this Privacy Policy from time to time. We will notify you of significant changes via the App. Continued use after updates means you accept the revised policy.",
      "section9Title": "Contact Us",
      "section9Body": "For privacy questions or data requests:\n\nEmail: privacy@egreet.in\nWebsite: https://egreet.in"
    },
    "terms": {
      "title": "Terms & Conditions",
      "lastUpdated": "Last updated: May 2025",
      "section1Title": "1. Acceptance of Terms",
      "section1Body": "By downloading, installing, or using Digi Bouquet (\"the App\"), you agree to be bound by these Terms and Conditions. If you do not agree, please do not use the App.",
      "section2Title": "2. Use of the App",
      "section2Body": "You may use the App only for lawful purposes and in accordance with these Terms. You agree not to use the App to send any content that is offensive, harmful, or violates the rights of others.",
      "section3Title": "3. User-Generated Content",
      "section3Body": "You are solely responsible for the messages, text, and other content you create and share through the App. E Greet does not endorse and is not responsible for any user-generated content.",
      "section4Title": "4. Intellectual Property",
      "section4Body": "All design elements, flower artwork, animations, and software in the App are the intellectual property of E Greet. You may not reproduce, distribute, or create derivative works without prior written permission.",
      "section5Title": "5. Third-Party Services",
      "section5Body": "The App may integrate with third-party services (such as iTunes for music preview). Your use of those services is subject to their respective terms. We are not responsible for any third-party content or services.",
      "section6Title": "6. Disclaimer of Warranties",
      "section6Body": "The App is provided \"as is\" without warranties of any kind. E Greet does not guarantee that the App will be error-free or uninterrupted.",
      "section7Title": "7. Limitation of Liability",
      "section7Body": "To the fullest extent permitted by law, E Greet shall not be liable for any indirect, incidental, special, or consequential damages arising from your use of the App.",
      "section8Title": "8. Changes to Terms",
      "section8Body": "We reserve the right to modify these Terms at any time. Continued use of the App after changes are posted constitutes acceptance of the new Terms.",
      "section9Title": "9. Contact",
      "section9Body": "If you have questions about these Terms, please contact us at hello@egreet.in."
    },
