    "privacy": {
      "title": "Política de Privacidad",
      "badge": "Tu privacidad nos importa",
      "lastUpdated": "Última actualización: Mayo de 2025",
      "section1Title": "1. Información que Recopilamos",
      "section1Body": "Recopilamos información mínima para operar la App. Esto incluye:\n\n- Ramos que creas (almacenados en Firebase Firestore)\n- Correo opcional si envías comentarios\n- Analíticas de uso anónimas para mejorar la App\n\nNo requerimos que crees una cuenta ni proporciones datos personales para usar la App.",
      "section2Title": "2. Cómo Usamos tu Información",
      "section2Body": "Usamos la información que recopilamos para:\n\n- Almacenar y entregar tus ramos digitales\n- Responder a los comentarios que envíes\n- Mejorar el rendimiento y funciones de la app\n- Detectar y prevenir el mal uso",
      "section3Title": "3. Almacenamiento y Seguridad de Datos",
      "section3Body": "Los datos de tu ramo se almacenan de forma segura en Google Firebase. Usamos cifrado y prácticas de seguridad estándar de la industria. Retenemos los datos del ramo durante 90 días después de su creación, tras lo cual pueden eliminarse automáticamente.",
      "section4Title": "4. Servicios de Terceros",
      "section4Body": "La App usa los siguientes servicios de terceros:\n\n- Google Firebase (almacenamiento de datos)\n- iTunes Search API (vistas previas de canciones - no se envían datos)\n- Sarvam AI (sugerencias opcionales de ramos con IA)\n\nCada servicio tiene su propia Política de Privacidad que rige el uso de datos.",
      "section5Title": "5. Cookies y Rastreo",
      "section5Body": "La App no usa cookies de rastreo. En la web, podemos usar almacenamiento local para recordar tus preferencias. No usamos rastreadores publicitarios ni vendemos tus datos a terceros.",
      "section6Title": "6. Privacidad de Menores",
      "section6Body": "Digi Bouquet no está dirigido a menores de 13 años. No recopilamos información personal de menores a sabiendas. Si crees que un menor nos ha proporcionado información personal, por favor contáctanos.",
      "section7Title": "7. Tus Derechos",
      "section7Body": "Tienes derecho a:\n\n- Acceder a los datos que tenemos sobre ti\n- Solicitar la eliminación de los datos de tus ramos\n- Excluirte de las analíticas\n\nPara ejercer estos derechos, contáctanos en privacy@egreet.in.",
      "section8Title": "8. Cambios en esta Política",
      "section8Body": "Podemos actualizar esta Política de Privacidad periódicamente. Te notificaremos de cambios importantes a través de la App. El uso continuo después de las actualizaciones significa que aceptas la política revisada.",
      "section9Title": "9. Contáctanos",
      "section9Body": "Para preguntas de privacidad o solicitudes de datos:\n\nCorreo: privacy@egreet.in\nSitio Web: https://egreet.in"
    },
    "terms": {
      "title": "Términos y Condiciones",
      "lastUpdated": "Última actualización: Mayo 2025",
      "section1Title": "1. Aceptación de los Términos",
      "section1Body": "Al descargar, instalar o usar Digi Bouquet (\"la App\"), aceptas estar sujeto a estos Términos y Condiciones. Si no estás de acuerdo, por favor no uses la App.",
      "section2Title": "2. Uso de la App",
      "section2Body": "Puedes usar la App solo con fines legales y de acuerdo con estos Términos. Aceptas no usar la App para enviar contenido ofensivo, dañino o que viole los derechos de otros.",
      "section3Title": "3. Contenido Generado por el Usuario",
      "section3Body": "Eres el único responsable de los mensajes, textos y otro contenido que crees y compartas a través de la App. E Greet no respalda ni es responsable por el contenido generado por los usuarios.",
      "section4Title": "4. Propiedad Intelectual",
      "section4Body": "Todos los elementos de diseño, arte de flores, animaciones y software en la App son propiedad intelectual de E Greet. No puedes reproducir, distribuir ni crear trabajos derivados sin permiso previo por escrito.",
      "section5Title": "5. Servicios de Terceros",
      "section5Body": "La App puede integrarse con servicios de terceros (como iTunes para previsualización de música). Tu uso de esos servicios está sujeto a sus respectivos términos. No somos responsables por contenido o servicios de terceros.",
      "section6Title": "6. Renuncia de Garantías",
      "section6Body": "La App se proporciona \"tal cual\" sin garantías de ningún tipo. E Greet no garantiza que la App estará libre de errores o interrupciones.",
      "section7Title": "7. Limitación de Responsabilidad",
      "section7Body": "En la máxima medida permitida por la ley, E Greet no será responsable de ningún daño indirecto, incidental, especial o consecuente derivado del uso de la App.",
      "section8Title": "8. Cambios a los Términos",
      "section8Body": "Nos reservamos el derecho de modificar estos Términos en cualquier momento. El uso continuo de la App después de publicar los cambios constituye la aceptación de los nuevos Términos.",
      "section9Title": "9. Contacto",
      "section9Body": "Si tienes preguntas sobre estos Términos, por favor contáctanos en hello@egreet.in."
    },
