    "privacy": {
      "title": "Politique de confidentialité",
      "badge": "Ta vie privée compte pour nous",
      "lastUpdated": "Dernière mise à jour : Mai 2025",
      "section1Title": "Informations que nous collectons",
      "section1Body": "Nous collectons un minimum d'informations pour faire fonctionner l'application. Cela inclut :\n\n- Les bouquets que tu crées (stockés dans Firebase Firestore)\n- Ton e-mail facultatif si tu envoies des commentaires\n- Des analyses d'utilisation anonymes pour améliorer l'application\n\nNous n'exigeons pas la création d'un compte ni d'informations personnelles pour utiliser l'application.",
      "section2Title": "Comment nous utilisons tes informations",
      "section2Body": "Nous utilisons les informations collectées pour :\n\n- Stocker et livrer tes bouquets numériques\n- Répondre aux commentaires que tu envoies\n- Améliorer les performances et les fonctionnalités de l'application\n- Détecter et prévenir les abus",
      "section3Title": "Stockage et sécurité des données",
      "section3Body": "Les données de ton bouquet sont stockées en toute sécurité sur Google Firebase. Nous utilisons des pratiques de chiffrement et de sécurité conformes aux normes de l'industrie. Nous conservons les données des bouquets pendant 90 jours après leur création, après quoi elles peuvent être supprimées automatiquement.",
      "section4Title": "Services tiers",
      "section4Body": "L'application utilise les services tiers suivants :\n\n- Google Firebase (stockage des données)\n- iTunes Search API (extraits musicaux - aucune donnée n'est envoyée)\n- Sarvam AI (suggestions facultatives de bouquets par l'IA)\n\nChaque service dispose de sa propre politique de confidentialité régissant l'utilisation des données.",
      "section5Title": "Cookies et suivi",
      "section5Body": "L'application n'utilise pas de cookies de suivi. Sur le web, nous pouvons utiliser le stockage local pour mémoriser tes préférences. Nous n'utilisons pas de traceurs publicitaires et ne vendons pas tes données à des tiers.",
      "section6Title": "Confidentialité des enfants",
      "section6Body": "Digi Bouquet ne s'adresse pas aux enfants de moins de 13 ans. Nous ne collectons pas sciemment d'informations personnelles auprès d'enfants. Si tu penses qu'un enfant nous a fourni des informations personnelles, merci de nous contacter.",
      "section7Title": "Tes droits",
      "section7Body": "Tu as le droit de :\n\n- Accéder aux données que nous détenons à ton sujet\n- Demander la suppression des données de tes bouquets\n- Refuser les analyses\n\nPour exercer ces droits, contacte-nous à privacy@egreet.in.",
      "section8Title": "Modifications de cette politique",
      "section8Body": "Nous pouvons mettre à jour cette politique de confidentialité de temps à autre. Nous t'informerons des changements importants via l'application. L'utilisation continue après les mises à jour signifie que tu acceptes la politique révisée.",
      "section9Title": "Nous contacter",
      "section9Body": "Pour toute question sur la confidentialité ou demande de données :\n\nE-mail : privacy@egreet.in\nSite web : https://egreet.in"
    },
    "terms": {
      "title": "Conditions générales",
      "lastUpdated": "Dernière mise à jour : Mai 2025",
      "section1Title": "1. Acceptation des conditions",
      "section1Body": "En téléchargeant, installant ou utilisant Digi Bouquet (« l'Application »), tu acceptes d'être lié par ces conditions générales. Si tu n'es pas d'accord, merci de ne pas utiliser l'application.",
      "section2Title": "2. Utilisation de l'application",
      "section2Body": "Tu ne peux utiliser l'application qu'à des fins légales et conformément à ces conditions. Tu acceptes de ne pas utiliser l'application pour envoyer du contenu offensant, nuisible ou violant les droits d'autrui.",
      "section3Title": "3. Contenu généré par l'utilisateur",
      "section3Body": "Tu es seul responsable des messages, textes et autres contenus que tu crées et partages via l'application. E Greet n'approuve pas et n'est pas responsable du contenu généré par les utilisateurs.",
      "section4Title": "4. Propriété intellectuelle",
      "section4Body": "Tous les éléments de design, illustrations de fleurs, animations et logiciels de l'application sont la propriété intellectuelle d'E Greet. Tu ne peux pas les reproduire, les distribuer ou créer des œuvres dérivées sans autorisation écrite préalable.",
      "section5Title": "5. Services tiers",
      "section5Body": "L'application peut intégrer des services tiers (comme iTunes pour les extraits musicaux). Ton utilisation de ces services est soumise à leurs propres conditions. Nous ne sommes pas responsables des contenus ou services tiers.",
      "section6Title": "6. Exclusion de garanties",
      "section6Body": "L'application est fournie « telle quelle », sans garantie d'aucune sorte. E Greet ne garantit pas que l'application sera exempte d'erreurs ou ininterrompue.",
      "section7Title": "7. Limitation de responsabilité",
      "section7Body": "Dans toute la mesure permise par la loi, E Greet ne saurait être tenu responsable des dommages indirects, accessoires, spéciaux ou consécutifs découlant de ton utilisation de l'application.",
      "section8Title": "8. Modification des conditions",
      "section8Body": "Nous nous réservons le droit de modifier ces conditions à tout moment. L'utilisation continue de l'application après la publication des modifications vaut acceptation des nouvelles conditions.",
      "section9Title": "9. Contact",
      "section9Body": "Si tu as des questions concernant ces conditions, contacte-nous à hello@egreet.in."
    },
