    "privacy": {
      "title": "Datenschutzrichtlinie",
      "badge": "Deine Privatsphäre ist uns wichtig",
      "lastUpdated": "Zuletzt aktualisiert: Mai 2025",
      "section1Title": "Informationen, die wir sammeln",
      "section1Body": "Wir sammeln nur minimale Informationen, um die App zu betreiben. Dazu gehören:\n\n- Blumensträuße, die du erstellst (gespeichert in Firebase Firestore)\n- Optionale E-Mail, wenn du Feedback sendest\n- Anonyme Nutzungsstatistiken zur Verbesserung der App\n\nDu musst kein Konto erstellen oder persönliche Daten angeben, um die App zu nutzen.",
      "section2Title": "Wie wir deine Informationen verwenden",
      "section2Body": "Wir verwenden die gesammelten Informationen, um:\n\n- Deine digitalen Blumensträuße zu speichern und zuzustellen\n- Auf dein Feedback zu antworten\n- Die Leistung und Funktionen der App zu verbessern\n- Missbrauch zu erkennen und zu verhindern",
      "section3Title": "Datenspeicherung & Sicherheit",
      "section3Body": "Die Daten deines Blumenstraußes werden sicher in Google Firebase gespeichert. Wir verwenden branchenübliche Verschlüsselungs- und Sicherheitspraktiken. Wir bewahren Blumenstrauß-Daten 90 Tage nach der Erstellung auf, danach werden sie möglicherweise automatisch gelöscht.",
      "section4Title": "Dienste von Drittanbietern",
      "section4Body": "Die App nutzt die folgenden Drittanbieter-Dienste:\n\n- Google Firebase (Datenspeicherung)\n- iTunes Search API (Song-Vorschauen - es werden keine Daten gesendet)\n- Sarvam AI (optionale KI-Blumenstrauß-Vorschläge)\n\nJeder Dienst hat seine eigene Datenschutzrichtlinie.",
      "section5Title": "Cookies & Tracking",
      "section5Body": "Die App verwendet keine Tracking-Cookies. Im Web verwenden wir möglicherweise den lokalen Speicher, um deine Einstellungen zu speichern. Wir verwenden keine Werbe-Tracker und verkaufen deine Daten nicht an Dritte.",
      "section6Title": "Datenschutz für Kinder",
      "section6Body": "Digi Bouquet richtet sich nicht an Kinder unter 13 Jahren. Wir erfassen nicht wissentlich personenbezogene Daten von Kindern. Wenn du glaubst, dass uns ein Kind personenbezogene Daten zur Verfügung gestellt hat, kontaktiere uns bitte.",
      "section7Title": "Deine Rechte",
      "section7Body": "Du hast das Recht:\n\n- Auf die Daten zuzugreifen, die wir über dich haben\n- Die Löschung deiner Blumenstrauß-Daten zu beantragen\n- Dem Tracking (Analytics) zu widersprechen\n\nUm diese Rechte auszuüben, kontaktiere uns unter privacy@egreet.in.",
      "section8Title": "Änderungen dieser Richtlinie",
      "section8Body": "Wir können diese Datenschutzrichtlinie von Zeit zu Zeit aktualisieren. Bei wesentlichen Änderungen werden wir dich über die App benachrichtigen. Die fortgesetzte Nutzung nach Updates bedeutet, dass du die überarbeitete Richtlinie akzeptierst.",
      "section9Title": "Kontaktiere uns",
      "section9Body": "Bei Fragen zum Datenschutz oder Datenanfragen:\n\nE-Mail: privacy@egreet.in\nWebsite: https://egreet.in"
    },
    "terms": {
      "title": "Nutzungsbedingungen",
      "lastUpdated": "Zuletzt aktualisiert: Mai 2025",
      "section1Title": "1. Annahme der Bedingungen",
      "section1Body": "Durch das Herunterladen, Installieren oder Nutzen von Digi Bouquet (\"die App\") erklärst du dich mit diesen Nutzungsbedingungen einverstanden. Wenn du nicht einverstanden bist, nutze die App bitte nicht.",
      "section2Title": "2. Nutzung der App",
      "section2Body": "Du darfst die App nur für rechtmäßige Zwecke und in Übereinstimmung mit diesen Bedingungen nutzen. Du erklärst dich damit einverstanden, die App nicht zu nutzen, um Inhalte zu senden, die anstößig oder schädlich sind oder die Rechte anderer verletzen.",
      "section3Title": "3. Benutzergenerierte Inhalte",
      "section3Body": "Du bist allein verantwortlich für die Nachrichten, Texte und anderen Inhalte, die du über die App erstellst und teilst. E Greet unterstützt keine benutzergenerierten Inhalte und ist nicht dafür verantwortlich.",
      "section4Title": "4. Geistiges Eigentum",
      "section4Body": "Alle Designelemente, Blumen-Grafiken, Animationen und Software in der App sind geistiges Eigentum von E Greet. Du darfst sie ohne vorherige schriftliche Genehmigung nicht reproduzieren, verbreiten oder abgeleitete Werke erstellen.",
      "section5Title": "5. Dienste von Drittanbietern",
      "section5Body": "Die App kann Dienste von Drittanbietern integrieren (wie iTunes für die Musikvorschau). Deine Nutzung dieser Dienste unterliegt deren jeweiligen Bedingungen. Wir sind nicht für Inhalte oder Dienste von Drittanbietern verantwortlich.",
      "section6Title": "6. Haftungsausschluss",
      "section6Body": "Die App wird \"wie besehen\" ohne jegliche Garantien bereitgestellt. E Greet garantiert nicht, dass die App fehlerfrei oder ununterbrochen funktioniert.",
      "section7Title": "7. Haftungsbeschränkung",
      "section7Body": "Soweit gesetzlich zulässig, haftet E Greet nicht für indirekte, zufällige, besondere oder Folgeschäden, die sich aus deiner Nutzung der App ergeben.",
      "section8Title": "8. Änderungen der Bedingungen",
      "section8Body": "Wir behalten uns das Recht vor, diese Bedingungen jederzeit zu ändern. Die fortgesetzte Nutzung der App nach der Veröffentlichung von Änderungen stellt die Annahme der neuen Bedingungen dar.",
      "section9Title": "9. Kontakt",
      "section9Body": "Wenn du Fragen zu diesen Bedingungen hast, kontaktiere uns bitte unter hello@egreet.in."
    },
