    "privacy": {
      "title": "سياسة الخصوصية",
      "badge": "خصوصيتك تهمنا",
      "lastUpdated": "آخر تحديث: مايو 2025",
      "section1Title": "المعلومات التي نجمعها",
      "section1Body": "نجمع الحد الأدنى من المعلومات لتشغيل التطبيق. يتضمن ذلك:\n\n- الباقات التي تصممها (مخزنة في Firebase Firestore)\n- البريد الإلكتروني الاختياري إذا قمت بإرسال ملاحظات\n- تحليلات استخدام مجهولة الهوية لتحسين التطبيق\n\nنحن لا نطلب منك إنشاء حساب أو تقديم تفاصيل شخصية لاستخدام التطبيق.",
      "section2Title": "كيف نستخدم معلوماتك",
      "section2Body": "نستخدم المعلومات التي نجمعها من أجل:\n\n- تخزين وتسليم باقاتك الرقمية\n- الرد على الملاحظات التي ترسلها\n- تحسين أداء التطبيق وميزاته\n- اكتشاف ومنع إساءة الاستخدام",
      "section3Title": "تخزين البيانات والأمان",
      "section3Body": "يتم تخزين بيانات باقتك بشكل آمن في Google Firebase. نحن نستخدم معايير تشفير وأمان معتمدة في الصناعة. نحتفظ ببيانات الباقة لمدة 90 يوماً بعد إنشائها، وبعد ذلك قد يتم حذفها تلقائياً.",
      "section4Title": "خدمات الطرف الثالث",
      "section4Body": "يستخدم التطبيق خدمات الطرف الثالث التالية:\n\n- Google Firebase (لتخزين البيانات)\n- iTunes Search API (للمعاينات الصوتية - لا يتم إرسال أي بيانات)\n- Sarvam AI (لاقتراحات الذكاء الاصطناعي الاختيارية)\n\nكل خدمة لها سياسة خصوصية خاصة بها تحكم استخدام البيانات.",
      "section5Title": "ملفات تعريف الارتباط والتتبع",
      "section5Body": "لا يستخدم التطبيق ملفات تعريف الارتباط للتتبع. على الويب، قد نستخدم التخزين المحلي لتذكر تفضيلاتك. لا نستخدم أدوات تتبع إعلانية ولا نبيع بياناتك لأطراف ثالثة.",
      "section6Title": "خصوصية الأطفال",
      "section6Body": "Digi Bouquet غير موجه للأطفال دون سن 13 عاماً. نحن لا نجمع معلومات شخصية من الأطفال عن قصد. إذا كنت تعتقد أن طفلاً قد قدم لنا معلومات شخصية، يرجى الاتصال بنا.",
      "section7Title": "حقوقك",
      "section7Body": "لديك الحق في:\n\n- الوصول إلى البيانات التي نحتفظ بها عنك\n- طلب حذف بيانات باقتك\n- إلغاء الاشتراك في التحليلات\n\nلممارسة هذه الحقوق، اتصل بنا على privacy@egreet.in.",
      "section8Title": "التغييرات على هذه السياسة",
      "section8Body": "قد نقوم بتحديث سياسة الخصوصية هذه من وقت لآخر. سنقوم بإبلاغك بالتغييرات المهمة عبر التطبيق. استمرارك في الاستخدام بعد التحديثات يعني قبولك للسياسة المنقحة.",
      "section9Title": "اتصل بنا",
      "section9Body": "لأسئلة الخصوصية أو طلبات البيانات:\n\nالبريد الإلكتروني: privacy@egreet.in\nالموقع الإلكتروني: https://egreet.in"
    },
    "terms": {
      "title": "الشروط والأحكام",
      "lastUpdated": "آخر تحديث: مايو 2025",
      "section1Title": "1. قبول الشروط",
      "section1Body": "من خلال تنزيل تطبيق Digi Bouquet (\"التطبيق\") أو تثبيته أو استخدامه، فإنك توافق على الالتزام بهذه الشروط والأحكام. إذا كنت لا توافق، يرجى عدم استخدام التطبيق.",
      "section2Title": "2. استخدام التطبيق",
      "section2Body": "يجوز لك استخدام التطبيق فقط لأغراض قانونية ووفقاً لهذه الشروط. أنت توافق على عدم استخدام التطبيق لإرسال أي محتوى مسيء أو ضار أو ينتهك حقوق الآخرين.",
      "section3Title": "3. المحتوى الذي ينشئه المستخدم",
      "section3Body": "أنت المسؤول الوحيد عن الرسائل والنصوص والمحتويات الأخرى التي تنشئها وتشاركها عبر التطبيق. لا تصادق E Greet على أي محتوى ينشئه المستخدم وليست مسؤولة عنه.",
      "section4Title": "4. الملكية الفكرية",
      "section4Body": "جميع عناصر التصميم والأعمال الفنية للزهور والرسوم المتحركة والبرامج في التطبيق هي ملكية فكرية لـ E Greet. لا يجوز لك إعادة إنتاجها أو توزيعها أو إنشاء أعمال مشتقة منها دون إذن كتابي مسبق.",
      "section5Title": "5. خدمات الطرف الثالث",
      "section5Body": "قد يتكامل التطبيق مع خدمات تابعة لجهات خارجية (مثل iTunes لمعاينة الموسيقى). يخضع استخدامك لتلك الخدمات لشروطها الخاصة. نحن لسنا مسؤولين عن أي محتوى أو خدمات لجهات خارجية.",
      "section6Title": "6. إخلاء المسؤولية عن الضمانات",
      "section6Body": "يتم توفير التطبيق \"كما هو\" دون أي ضمانات من أي نوع. لا تضمن E Greet أن التطبيق سيكون خالياً من الأخطاء أو دون انقطاع.",
      "section7Title": "7. حدود المسؤولية",
      "section7Body": "إلى أقصى حد يسمح به القانون، لن تكون E Greet مسؤولة عن أي أضرار غير مباشرة أو عرضية أو خاصة أو تبعية تنشأ عن استخدامك للتطبيق.",
      "section8Title": "8. التغييرات على الشروط",
      "section8Body": "نحتفظ بالحق في تعديل هذه الشروط في أي وقت. الاستمرار في استخدام التطبيق بعد نشر التغييرات يشكل قبولاً للشروط الجديدة.",
      "section9Title": "9. الاتصال",
      "section9Body": "إذا كانت لديك أسئلة حول هذه الشروط، يرجى الاتصال بنا على hello@egreet.in."
    },
