    "privacy": {
      "title": "개인정보 처리방침",
      "badge": "여러분의 개인정보는 소중합니다",
      "lastUpdated": "최종 수정일: 2025년 5월",
      "section1Title": "1. 수집하는 정보",
      "section1Body": "저희는 앱 운영에 필요한 최소한의 정보만 수집합니다:\n\n- 여러분이 만든 꽃다발 데이터 (Firebase Firestore에 저장)\n- 의견을 보낼 때 선택적으로 입력하는 이메일 주소\n- 앱 개선을 위한 익명화된 사용 통계\n\n앱을 사용하기 위해 반드시 회원가입을 하거나 개인정보를 제공할 필요는 없습니다.",
      "section2Title": "2. 정보의 사용 목적",
      "section2Body": "수집된 정보는 다음 목적으로 사용됩니다:\n\n- 디지털 꽃다발 저장 및 상대방에게 전달\n- 보내주신 소중한 의견에 대한 답변\n- 앱 성능 향상 및 기능 개선\n- 오남용 감지 및 방지",
      "section3Title": "3. 데이터 저장 및 보안",
      "section3Body": "꽃다발 데이터는 Google Firebase에 안전하게 저장됩니다. 저희는 업계 표준 암호화 및 보안 정책을 따르고 있습니다. 꽃다발 데이터는 생성 후 90일 동안 보관되며, 그 이후에는 자동으로 삭제될 수 있습니다.",
      "section4Title": "4. 타사 서비스",
      "section4Body": "앱은 다음 타사 서비스를 사용합니다:\n\n- Google Firebase (데이터 저장)\n- iTunes Search API (노래 미리듣기 - 어떠한 개인정보도 전송되지 않음)\n- Sarvam AI (선택적 AI 꽃다발 추천 기능)\n\n각 서비스는 자체 개인정보 처리방침에 따라 데이터를 관리합니다.",
      "section5Title": "5. 쿠키 및 추적",
      "section5Body": "앱은 사용자를 추적하는 쿠키를 사용하지 않습니다. 웹 환경에서는 설정 저장을 위해 로컬 스토리지를 사용할 수 있습니다. 광고 추적기를 사용하거나 여러분의 데이터를 제3자에게 판매하지 않습니다.",
      "section6Title": "6. 아동의 개인정보",
      "section6Body": "Digi Bouquet은 만 13세 미만 아동을 대상으로 하지 않으며, 아동의 개인정보를 의도적으로 수집하지 않습니다. 아동이 개인정보를 제공했다고 생각되시면 저희에게 연락해 주세요.",
      "section7Title": "7. 사용자의 권리",
      "section7Body": "여러분은 다음과 같은 권리가 있습니다:\n\n- 저희가 보유한 데이터 확인\n- 꽃다발 데이터 삭제 요청\n- 익명 통계 수집 거부\n\n이러한 권리를 행사하시려면 privacy@egreet.in으로 연락해 주세요.",
      "section8Title": "8. 처리방침 변경",
      "section8Body": "본 개인정보 처리방침은 수시로 업데이트될 수 있습니다. 중요한 변경 사항은 앱을 통해 알려드립니다. 업데이트 후에도 앱을 계속 사용하시면 변경된 정책에 동의한 것으로 간주됩니다.",
      "section9Title": "9. 연락처",
      "section9Body": "개인정보 관련 문의나 데이터 관련 요청이 있으시면 아래로 연락해 주세요:\n\n이메일: privacy@egreet.in\n웹사이트: https://egreet.in"
    },
    "terms": {
      "title": "이용약관",
      "lastUpdated": "최종 수정일: 2025년 5월",
      "section1Title": "1. 약관 동의",
      "section1Body": "Digi Bouquet('앱')을 다운로드, 설치 또는 사용함으로써 귀하는 본 이용약관에 동의하게 됩니다. 동의하지 않으실 경우 앱 사용을 중단해 주시기 바랍니다.",
      "section2Title": "2. 앱의 사용",
      "section2Body": "귀하는 합법적인 목적으로만 앱을 사용해야 합니다. 다른 사람에게 불쾌감을 주거나, 해를 끼치거나, 타인의 권리를 침해하는 콘텐츠를 보내는 데 이 앱을 사용해서는 안 됩니다.",
      "section3Title": "3. 사용자 생성 콘텐츠",
      "section3Body": "앱을 통해 귀하가 만들고 공유하는 메시지, 텍스트 및 모든 콘텐츠에 대한 책임은 전적으로 귀하에게 있습니다. E Greet은 사용자가 생성한 콘텐츠를 보증하지 않으며 이에 대한 책임을 지지 않습니다.",
      "section4Title": "4. 지적 재산권",
      "section4Body": "앱 내 모든 디자인 요소, 꽃 아트워크, 애니메이션 및 소프트웨어는 E Greet의 지적 재산입니다. 사전 서면 허가 없이 이를 복제, 배포하거나 2차적 저작물을 만들 수 없습니다.",
      "section5Title": "5. 타사 서비스",
      "section5Body": "앱은 타사 서비스(음악 미리듣기를 위한 iTunes 등)와 연동될 수 있습니다. 해당 서비스 이용은 각 타사의 약관을 따르며, 당사는 타사 콘텐츠나 서비스에 대해 책임을 지지 않습니다.",
      "section6Title": "6. 보증 부인",
      "section6Body": "앱은 '있는 그대로' 제공되며 어떠한 종류의 보증도 명시하지 않습니다. E Greet은 앱의 오류가 없거나 중단 없이 작동할 것이라고 보장하지 않습니다.",
      "section7Title": "7. 책임의 한계",
      "section7Body": "법이 허용하는 최대 한도 내에서, E Greet은 앱 사용으로 인해 발생하는 모든 간접적, 우발적, 특별 혹은 결과적 손해에 대해 책임을 지지 않습니다.",
      "section8Title": "8. 약관 변경",
      "section8Body": "당사는 언제든지 본 약관을 수정할 권리가 있습니다. 변경 사항이 게시된 후 앱을 계속 사용하는 것은 새 약관에 동의함을 의미합니다.",
      "section9Title": "9. 연락처",
      "section9Body": "본 약관에 대해 궁금한 점이 있으시면 hello@egreet.in으로 문의해 주세요."
    },
