    "privacy": {
      "title": "隐私政策",
      "badge": "您的隐私对我们至关重要",
      "lastUpdated": "最后更新时间：2025年5月",
      "section1Title": "我们收集的信息",
      "section1Body": "为了运营本应用，我们会收集极少的信息。这些包括：\n\n- 您制作的花束（存储在 Firebase Firestore 中）\n- 提交反馈时可选的电子邮件\n- 用于改进应用的匿名使用情况分析\n\n使用本应用不要求您必须创建账号或提供个人详细信息。",
      "section2Title": "我们如何使用您的信息",
      "section2Body": "我们将收集的信息用于：\n\n- 存储并送达您的数字花束\n- 回复您提交的反馈\n- 改进应用的性能和功能\n- 检测并防止滥用行为",
      "section3Title": "数据存储与安全",
      "section3Body": "您的花束数据安全地存储在 Google Firebase 中。我们采用行业标准的加密和安全措施。我们会在花束创建后保留数据 90 天，之后可能会被自动删除。",
      "section4Title": "第三方服务",
      "section4Body": "本应用使用以下第三方服务：\n\n- Google Firebase（数据存储）\n- iTunes Search API（歌曲预览 - 不发送任何数据）\n- Sarvam AI（可选的 AI 花束建议）\n\n每项服务均有其自身的隐私政策，以此管理数据的使用。",
      "section5Title": "Cookie 与追踪",
      "section5Body": "本应用不使用追踪 Cookie。在网页端，我们可能会使用本地存储来记住您的偏好。我们不使用广告追踪器，也不会将您的数据出售给第三方。",
      "section6Title": "儿童隐私",
      "section6Body": "Digi Bouquet 并非针对 13 岁以下的儿童设计。我们不会有意收集儿童的个人信息。如果您认为有儿童向我们提供了个人信息，请与我们联系。",
      "section7Title": "您的权利",
      "section7Body": "您有权：\n\n- 访问我们持有的关于您的数据\n- 请求删除您的花束数据\n- 选择退出数据分析\n\n如需行使这些权利，请通过 privacy@egreet.in 联系我们。",
      "section8Title": "本政策的变更",
      "section8Body": "我们可能会不时更新本隐私政策。如有重大变更，我们将通过应用通知您。更新后继续使用即表示您接受修订后的政策。",
      "section9Title": "联系我们",
      "section9Body": "如有隐私相关问题或数据请求，请联系：\n\n电子邮件：privacy@egreet.in\n网站：https://egreet.in"
    },
    "terms": {
      "title": "条款与条件",
      "lastUpdated": "最后更新时间：2025年5月",
      "section1Title": "1. 接受条款",
      "section1Body": "下载、安装或使用 Digi Bouquet（简称“本应用”），即表示您同意受这些条款与条件的约束。如果您不同意，请勿使用本应用。",
      "section2Title": "2. 应用的使用",
      "section2Body": "您只能出于合法目的并按照本条款使用本应用。您同意不使用本应用发送任何具有攻击性、有害或侵犯他人权利的内容。",
      "section3Title": "3. 用户生成内容",
      "section3Body": "您对通过本应用创建和分享的留言、文本和其他内容承担全部责任。E Greet 不为任何用户生成内容背书，也不对其负责。",
      "section4Title": "4. 知识产权",
      "section4Body": "本应用中的所有设计元素、花卉图片、动画和软件均为 E Greet 的知识产权。未经事先书面许可，您不得复制、分发或创建衍生作品。",
      "section5Title": "5. 第三方服务",
      "section5Body": "本应用可能会集成第三方服务（如用于音乐预览的 iTunes）。您对这些服务的使用受其各自条款的约束。我们不对任何第三方内容或服务负责。",
      "section6Title": "6. 免责声明",
      "section6Body": "本应用按“原样”提供，不提供任何形式的担保。E Greet 不保证本应用不会出现错误或中断。",
      "section7Title": "7. 责任限制",
      "section7Body": "在法律允许的最大范围内，对于因您使用本应用而引起的任何间接、附带、特殊或后果性损害，E Greet 概不负责。",
      "section8Title": "8. 条款的变更",
      "section8Body": "我们保留随时修改这些条款的权利。在发布更改后继续使用本应用即表示接受新条款。",
      "section9Title": "9. 联系方式",
      "section9Body": "如果您对这些条款有任何疑问，请通过 hello@egreet.in 联系我们。"
    },
