    "privacy": {
      "title": "プライバシーポリシー",
      "badge": "お客様のプライバシーを大切にしています",
      "lastUpdated": "最終更新日：2025年5月",
      "section1Title": "1. 収集する情報",
      "section1Body": "当アプリの運営において、以下の必要最小限の情報を収集します：\n\n- 作成したブーケ（Firebase Firestoreに保存）\n- フィードバック送信時のメールアドレス（任意）\n- アプリ改善のための匿名の利用状況データ\n\nアプリの利用にアカウント作成や個人情報の提供は必須ではありません。",
      "section2Title": "2. 情報の利用目的",
      "section2Body": "収集した情報は以下の目的で利用されます：\n\n- デジタルブーケの保存および配信\n- お寄せいただいたフィードバックへの回答\n- アプリのパフォーマンスと機能の改善\n- 不正利用の検知および防止",
      "section3Title": "3. データの保存とセキュリティ",
      "section3Body": "ブーケのデータはGoogle Firebaseに安全に保存されます。業界標準の暗号化およびセキュリティ対策を講じています。ブーケデータは作成後90日間保持され、その後自動的に削除される場合があります。",
      "section4Title": "4. サードパーティサービス",
      "section4Body": "当アプリは以下のサードパーティサービスを利用しています：\n\n- Google Firebase（データ保存）\n- iTunes Search API（楽曲の試聴 - データ送信なし）\n- Sarvam AI（オプションのAIブーケ提案）\n\n各サービスにおけるデータの取り扱いは、それぞれのプライバシーポリシーに準じます。",
      "section5Title": "5. クッキーとトラッキング",
      "section5Body": "当アプリはトラッキングクッキーを使用しません。ウェブ版では、設定を記憶するためにローカルストレージを使用する場合があります。広告トラッカーの使用や、第三者へのデータ販売は一切行いません。",
      "section6Title": "6. お子様のプライバシー",
      "section6Body": "Digi Bouquetは13歳未満のお子様を対象としていません。意図的にお子様から個人情報を収集することはありません。お子様が個人情報を提供したと思われる場合は、ご連絡ください。",
      "section7Title": "7. お客様の権利",
      "section7Body": "お客様には以下の権利があります：\n\n- 保持しているお客様のデータへのアクセス\n- ブーケデータの削除リクエスト\n- アナリティクス（解析）のオプトアウト\n\nこれらの権利を行使する場合は、privacy@egreet.in までご連絡ください。",
      "section8Title": "8. 本ポリシーの変更",
      "section8Body": "プライバシーポリシーは随時更新される場合があります。重要な変更がある場合はアプリ内でお知らせします。更新後も引き続きご利用いただいた場合、改定されたポリシーに同意したものとみなされます。",
      "section9Title": "9. お問い合わせ",
      "section9Body": "プライバシーに関するご質問やデータに関するリクエストは、以下までお問い合わせください：\n\nメール: privacy@egreet.in\nウェブサイト: https://egreet.in"
    },
    "terms": {
      "title": "利用規約",
      "lastUpdated": "最終更新日：2025年5月",
      "section1Title": "1. 規約の同意",
      "section1Body": "Digi Bouquet（以下「本アプリ」）をダウンロード、インストール、または使用することにより、本利用規約に同意したものとみなされます。同意されない場合は、本アプリの使用をお控えください。",
      "section2Title": "2. アプリの利用",
      "section2Body": "本アプリは、合法的な目的かつ本規約に従ってのみ使用できます。不快なコンテンツ、有害なコンテンツ、または他者の権利を侵害するコンテンツの送信に本アプリを使用しないことに同意するものとします。",
      "section3Title": "3. ユーザー生成コンテンツ",
      "section3Body": "本アプリを通じて作成および共有するメッセージ、テキスト、その他のコンテンツは、お客様ご自身の責任となります。E Greetは、ユーザー生成コンテンツを推奨せず、一切の責任を負いません。",
      "section4Title": "4. 知的財産権",
      "section4Body": "本アプリ内のすべてのデザイン要素、お花のアートワーク、アニメーション、ソフトウェアは、E Greetの知的財産です。事前の書面による許可なく、複製、配布、派生物の作成を行うことはできません。",
      "section5Title": "5. サードパーティサービス",
      "section5Body": "本アプリはサードパーティサービス（音楽プレビュー用のiTunesなど）と連携する場合があります。これらのサービスの利用は、それぞれの規約に従うものとします。当社は、サードパーティのコンテンツまたはサービスについて責任を負いません。",
      "section6Title": "6. 免責事項",
      "section6Body": "本アプリは、いかなる種類の保証もなく「現状有姿」で提供されます。E Greetは、本アプリがエラーなく動作すること、または中断されないことを保証しません。",
      "section7Title": "7. 責任の制限",
      "section7Body": "法律で認められる最大限の範囲において、E Greetは、本アプリの利用に起因するいかなる間接的、偶発的、特別、または派生的な損害についても責任を負いません。",
      "section8Title": "8. 規約の変更",
      "section8Body": "当社は、いつでも本規約を変更する権利を留保します。変更が掲示された後も引き続き本アプリを使用した場合、新しい規約に同意したものとみなされます。",
      "section9Title": "9. お問い合わせ",
      "section9Body": "本規約に関するご質問は、hello@egreet.in までお問い合わせください。"
    },
