    "privacy": {
      "title": "Política de Privacidade",
      "badge": "Sua privacidade é importante para nós",
      "lastUpdated": "Última atualização: Maio de 2025",
      "section1Title": "Informações que Coletamos",
      "section1Body": "Coletamos o mínimo de informações para operar o Aplicativo. Isso inclui:\n\n- Buquês que você cria (armazenados no Firebase Firestore)\n- E-mail opcional caso envie um feedback\n- Análises de uso anônimas para melhorar o App\n\nNão exigimos que você crie uma conta ou forneça dados pessoais para usar o Aplicativo.",
      "section2Title": "Como Usamos Suas Informações",
      "section2Body": "Usamos as informações que coletamos para:\n\n- Armazenar e entregar seus buquês digitais\n- Responder aos feedbacks enviados\n- Melhorar o desempenho e os recursos do aplicativo\n- Detectar e evitar o uso indevido",
      "section3Title": "Armazenamento de Dados e Segurança",
      "section3Body": "Os dados do seu buquê são armazenados com segurança no Google Firebase. Usamos criptografia e práticas de segurança padrão da indústria. Mantemos os dados do buquê por 90 dias após a criação, após os quais eles podem ser excluídos automaticamente.",
      "section4Title": "Serviços de Terceiros",
      "section4Body": "O Aplicativo usa os seguintes serviços de terceiros:\n\n- Google Firebase (armazenamento de dados)\n- API do iTunes Search (prévias de músicas - nenhum dado é enviado)\n- Sarvam AI (sugestões opcionais de buquês por IA)\n\nCada serviço possui sua própria Política de Privacidade que rege o uso de dados.",
      "section5Title": "Cookies e Rastreamento",
      "section5Body": "O Aplicativo não usa cookies de rastreamento. Na web, podemos usar armazenamento local para lembrar suas preferências. Não usamos rastreadores de publicidade e nem vendemos seus dados a terceiros.",
      "section6Title": "Privacidade Infantil",
      "section6Body": "O Digi Bouquet não é direcionado a crianças menores de 13 anos. Não coletamos intencionalmente informações pessoais de crianças. Se você acredita que uma criança nos forneceu informações pessoais, entre em contato conosco.",
      "section7Title": "Seus Direitos",
      "section7Body": "Você tem o direito de:\n\n- Acessar os dados que mantemos sobre você\n- Solicitar a exclusão dos dados do seu buquê\n- Cancelar o uso de dados analíticos\n\nPara exercer esses direitos, entre em contato conosco pelo e-mail privacy@egreet.in.",
      "section8Title": "Alterações nesta Política",
      "section8Body": "Podemos atualizar esta Política de Privacidade de tempos em tempos. Notificaremos sobre mudanças significativas através do Aplicativo. O uso contínuo após as atualizações significa que você aceita a política revisada.",
      "section9Title": "Fale Conosco",
      "section9Body": "Para dúvidas sobre privacidade ou solicitações de dados:\n\nE-mail: privacy@egreet.in\nSite: https://egreet.in"
    },
    "terms": {
      "title": "Termos e Condições",
      "lastUpdated": "Última atualização: Maio de 2025",
      "section1Title": "1. Aceitação dos Termos",
      "section1Body": "Ao baixar, instalar ou usar o Digi Bouquet (\"o Aplicativo\"), você concorda em ficar vinculado a estes Termos e Condições. Se você não concordar, por favor, não use o Aplicativo.",
      "section2Title": "2. Uso do Aplicativo",
      "section2Body": "Você pode usar o Aplicativo apenas para fins lícitos e de acordo com estes Termos. Você concorda em não usar o Aplicativo para enviar qualquer conteúdo que seja ofensivo, prejudicial ou que viole os direitos de terceiros.",
      "section3Title": "3. Conteúdo Gerado pelo Usuário",
      "section3Body": "Você é o único responsável pelas mensagens, textos e outros conteúdos que cria e compartilha pelo Aplicativo. O E Greet não endossa e não se responsabiliza por nenhum conteúdo gerado pelo usuário.",
      "section4Title": "4. Propriedade Intelectual",
      "section4Body": "Todos os elementos de design, artes de flores, animações e softwares no Aplicativo são de propriedade intelectual do E Greet. Você não pode reproduzir, distribuir ou criar trabalhos derivados sem permissão prévia por escrito.",
      "section5Title": "5. Serviços de Terceiros",
      "section5Body": "O Aplicativo pode ser integrado a serviços de terceiros (como o iTunes para visualização de músicas). O uso desses serviços está sujeito aos seus respectivos termos. Não somos responsáveis ​​por qualquer conteúdo ou serviço de terceiros.",
      "section6Title": "6. Isenção de Garantias",
      "section6Body": "O Aplicativo é fornecido \"como está\", sem garantias de qualquer tipo. O E Greet não garante que o Aplicativo estará livre de erros ou que não sofrerá interrupções.",
      "section7Title": "7. Limitação de Responsabilidade",
      "section7Body": "Até a extensão máxima permitida por lei, o E Greet não se responsabiliza por quaisquer danos indiretos, incidentais, especiais ou consequentes decorrentes do seu uso do Aplicativo.",
      "section8Title": "8. Alterações nos Termos",
      "section8Body": "Reservamo-nos o direito de modificar estes Termos a qualquer momento. O uso contínuo do Aplicativo após as alterações publicadas constitui a aceitação dos novos Termos.",
      "section9Title": "9. Contato",
      "section9Body": "Se você tiver dúvidas sobre estes Termos, entre em contato conosco pelo e-mail hello@egreet.in."
    },
