    "privacy": {
      "title": "Informativa sulla privacy",
      "badge": "La tua privacy è importante per noi",
      "lastUpdated": "Ultimo aggiornamento: Maggio 2025",
      "section1Title": "Informazioni che raccogliamo",
      "section1Body": "Raccogliamo informazioni minime per il funzionamento dell'App. Queste includono:\n\n- I bouquet che crei (archiviati su Firebase Firestore)\n- E-mail opzionale se invii un feedback\n- Analisi di utilizzo anonime per migliorare l'App\n\nNon è necessario creare un account o fornire dati personali per utilizzare l'App.",
      "section2Title": "Come utilizziamo le tue informazioni",
      "section2Body": "Utilizziamo le informazioni che raccogliamo per:\n\n- Archiviare e consegnare i tuoi bouquet digitali\n- Rispondere ai feedback che invii\n- Migliorare le prestazioni e le funzionalità dell'App\n- Rilevare e prevenire abusi",
      "section3Title": "Archiviazione e sicurezza dei dati",
      "section3Body": "I dati dei tuoi bouquet sono archiviati in modo sicuro su Google Firebase. Utilizziamo crittografia e pratiche di sicurezza standard del settore. Conserviamo i dati dei bouquet per 90 giorni dalla creazione, dopodiché potrebbero essere eliminati automaticamente.",
      "section4Title": "Servizi di terze parti",
      "section4Body": "L'App utilizza i seguenti servizi di terze parti:\n\n- Google Firebase (archiviazione dati)\n- API di iTunes Search (anteprime dei brani - nessun dato viene inviato)\n- Sarvam AI (suggerimenti IA opzionali per i bouquet)\n\nOgni servizio ha la propria Informativa sulla privacy che regola l'uso dei dati.",
      "section5Title": "Cookie e tracciamento",
      "section5Body": "L'App non utilizza cookie di tracciamento. Sul web, potremmo utilizzare l'archiviazione locale per ricordare le tue preferenze. Non utilizziamo tracker pubblicitari né vendiamo i tuoi dati a terzi.",
      "section6Title": "Privacy dei minori",
      "section6Body": "Digi Bouquet non è rivolta ai minori di 13 anni. Non raccogliamo consapevolmente informazioni personali di bambini. Se ritieni che un bambino ci abbia fornito informazioni personali, ti preghiamo di contattarci.",
      "section7Title": "I tuoi diritti",
      "section7Body": "Hai il diritto di:\n\n- Accedere ai dati che conserviamo su di te\n- Richiedere l'eliminazione dei dati dei tuoi bouquet\n- Rinunciare alle analisi (opt-out)\n\nPer esercitare questi diritti, contattaci all'indirizzo privacy@egreet.in.",
      "section8Title": "Modifiche a questa informativa",
      "section8Body": "Potremmo aggiornare questa Informativa sulla privacy di tanto in tanto. Ti informeremo dei cambiamenti significativi tramite l'App. L'uso continuato dopo gli aggiornamenti implica l'accettazione dell'informativa modificata.",
      "section9Title": "Contattaci",
      "section9Body": "Per domande sulla privacy o richieste sui dati:\n\nE-mail: privacy@egreet.in\nSito web: https://egreet.in"
    },
    "terms": {
      "title": "Termini e condizioni",
      "lastUpdated": "Ultimo aggiornamento: Maggio 2025",
      "section1Title": "1. Accettazione dei termini",
      "section1Body": "Scaricando, installando o utilizzando Digi Bouquet (\"l'App\"), accetti di essere vincolato da questi Termini e Condizioni. Se non accetti, ti preghiamo di non utilizzare l'App.",
      "section2Title": "2. Uso dell'App",
      "section2Body": "Puoi utilizzare l'App solo per scopi legali e in conformità con questi Termini. Accetti di non utilizzare l'App per inviare contenuti offensivi, dannosi o che violano i diritti altrui.",
      "section3Title": "3. Contenuti generati dagli utenti",
      "section3Body": "Sei l'unico responsabile dei messaggi, del testo e degli altri contenuti che crei e condividi tramite l'App. E Greet non approva e non è responsabile per alcun contenuto generato dagli utenti.",
      "section4Title": "4. Proprietà intellettuale",
      "section4Body": "Tutti gli elementi di design, la grafica dei fiori, le animazioni e il software presenti nell'App sono proprietà intellettuale di E Greet. Non puoi riprodurre, distribuire o creare opere derivate senza previa autorizzazione scritta.",
      "section5Title": "5. Servizi di terze parti",
      "section5Body": "L'App potrebbe integrarsi con servizi di terze parti (come iTunes per l'anteprima musicale). L'utilizzo di tali servizi è soggetto ai rispettivi termini. Non siamo responsabili per contenuti o servizi di terze parti.",
      "section6Title": "6. Esclusione di garanzie",
      "section6Body": "L'App è fornita \"così com'è\" senza garanzie di alcun tipo. E Greet non garantisce che l'App sia priva di errori o interruzioni.",
      "section7Title": "7. Limitazione di responsabilità",
      "section7Body": "Nella misura massima consentita dalla legge, E Greet non sarà responsabile per alcun danno indiretto, incidentale, speciale o consequenziale derivante dall'uso dell'App.",
      "section8Title": "8. Modifiche ai Termini",
      "section8Body": "Ci riserviamo il diritto di modificare questi Termini in qualsiasi momento. L'uso continuato dell'App dopo la pubblicazione delle modifiche costituisce l'accettazione dei nuovi Termini.",
      "section9Title": "9. Contatti",
      "section9Body": "In caso di domande su questi Termini, contattaci all'indirizzo hello@egreet.in."
    },
