    "privacy": {
      "title": "Политика конфиденциальности",
      "badge": "Твоя конфиденциальность важна для нас",
      "lastUpdated": "Последнее обновление: май 2025 г.",
      "section1Title": "Информация, которую мы собираем",
      "section1Body": "Мы собираем минимум данных для работы приложения:\n\n- Созданные тобой букеты (хранятся в Firebase Firestore)\n- Дополнительный email при отправке отзыва\n- Анонимную аналитику для улучшения работы\n\nДля использования приложения не обязательно создавать аккаунт или указывать личные данные.",
      "section2Title": "Как мы используем твою информацию",
      "section2Body": "Мы используем собранные данные, чтобы:\n\n- Хранить и доставлять цифровые букеты\n- Отвечать на твои отзывы\n- Улучшать работу приложения и его функции\n- Выявлять и предотвращать злоупотребления",
      "section3Title": "Хранение и безопасность данных",
      "section3Body": "Данные твоих букетов надежно хранятся в Google Firebase. Мы используем современные стандарты шифрования и безопасности. Данные букета хранятся 90 дней после создания, затем они могут быть удалены автоматически.",
      "section4Title": "Сторонние сервисы",
      "section4Body": "Приложение использует следующие сторонние сервисы:\n\n- Google Firebase (хранение данных)\n- iTunes Search API (превью песен — данные не передаются)\n- Sarvam AI (предложения ИИ для букетов — по желанию)\n\nКаждый сервис имеет свою Политику конфиденциальности.",
      "section5Title": "Файлы cookie и отслеживание",
      "section5Body": "Приложение не использует cookie-файлы для отслеживания. В веб-версии мы можем использовать локальное хранилище для сохранения твоих настроек. Мы не используем рекламные трекеры и не продаем твои данные.",
      "section6Title": "Конфиденциальность детей",
      "section6Body": "Digi Bouquet не предназначен для детей младше 13 лет. Мы намеренно не собираем личные данные детей. Если ты считаешь, что ребенок передал нам свои данные, свяжись с нами.",
      "section7Title": "Твои права",
      "section7Body": "У тебя есть право:\n\n- Получить доступ к данным, которые мы храним о тебе\n- Запросить удаление данных твоих букетов\n- Отказаться от аналитики\n\nЧтобы воспользоваться этими правами, напиши нам на privacy@egreet.in.",
      "section8Title": "Изменения в Политике",
      "section8Body": "Мы можем время от времени обновлять эту Политику. Мы сообщим о значимых изменениях в приложении. Продолжение использования означает твое согласие с новой политикой.",
      "section9Title": "Связаться с нами",
      "section9Body": "По вопросам конфиденциальности и данных:\n\nEmail: privacy@egreet.in\nСайт: https://egreet.in"
    },
