    "privacy": {
      "title": "Kebijakan Privasi",
      "badge": "Privasi Anda penting bagi kami",
      "lastUpdated": "Terakhir diperbarui: Mei 2025",
      "section1Title": "Informasi yang Kami Kumpulkan",
      "section1Body": "Kami mengumpulkan informasi minimal untuk mengoperasikan Aplikasi. Ini termasuk:\n\n- Buket yang Anda buat (disimpan di Firebase Firestore)\n- Email opsional jika Anda mengirim umpan balik\n- Analitik penggunaan anonim untuk meningkatkan Aplikasi\n\nKami tidak mengharuskan Anda membuat akun atau memberikan detail pribadi untuk menggunakan Aplikasi.",
      "section2Title": "Bagaimana Kami Menggunakan Informasi Anda",
      "section2Body": "Kami menggunakan informasi yang kami kumpulkan untuk:\n\n- Menyimpan dan mengirimkan buket digital Anda\n- Menanggapi umpan balik yang Anda kirimkan\n- Meningkatkan kinerja dan fitur aplikasi\n- Mendeteksi dan mencegah penyalahgunaan",
      "section3Title": "Penyimpanan & Keamanan Data",
      "section3Body": "Data buket Anda disimpan secara aman di Google Firebase. Kami menggunakan praktik enkripsi dan keamanan standar industri. Kami menyimpan data buket selama 90 hari setelah dibuat, setelah itu dapat dihapus secara otomatis.",
      "section4Title": "Layanan Pihak Ketiga",
      "section4Body": "Aplikasi ini menggunakan layanan pihak ketiga berikut:\n\n- Google Firebase (penyimpanan data)\n- iTunes Search API (pratinjau lagu - tidak ada data yang dikirim)\n- Sarvam AI (opsional untuk saran buket AI)\n\nSetiap layanan memiliki Kebijakan Privasinya sendiri yang mengatur penggunaan data.",
      "section5Title": "Cookie & Pelacakan",
      "section5Body": "Aplikasi tidak menggunakan cookie pelacakan. Di web, kami mungkin menggunakan penyimpanan lokal untuk mengingat preferensi Anda. Kami tidak menggunakan pelacak iklan atau menjual data Anda kepada pihak ketiga.",
      "section6Title": "Privasi Anak",
      "section6Body": "Digi Bouquet tidak ditujukan untuk anak-anak di bawah 13 tahun. Kami tidak secara sadar mengumpulkan informasi pribadi dari anak-anak. Jika Anda yakin seorang anak telah memberi kami informasi pribadi, silakan hubungi kami.",
      "section7Title": "Hak Anda",
      "section7Body": "Anda berhak untuk:\n\n- Mengakses data yang kami simpan tentang Anda\n- Meminta penghapusan data buket Anda\n- Keluar dari analitik\n\nUntuk menggunakan hak-hak ini, hubungi kami di privacy@egreet.in.",
      "section8Title": "Perubahan pada Kebijakan Ini",
      "section8Body": "Kami dapat memperbarui Kebijakan Privasi ini dari waktu ke waktu. Kami akan memberi tahu Anda tentang perubahan signifikan melalui Aplikasi. Penggunaan berkelanjutan setelah pembaruan berarti Anda menerima kebijakan yang direvisi.",
      "section9Title": "Hubungi Kami",
      "section9Body": "Untuk pertanyaan privasi atau permintaan data:\n\nEmail: privacy@egreet.in\nSitus web: https://egreet.in"
    },
    "terms": {
      "title": "Syarat & Ketentuan",
      "lastUpdated": "Terakhir diperbarui: Mei 2025",
      "section1Title": "1. Penerimaan Syarat",
      "section1Body": "Dengan mengunduh, menginstal, atau menggunakan Digi Bouquet (\"Aplikasi\"), Anda setuju untuk terikat oleh Syarat dan Ketentuan ini. Jika Anda tidak setuju, harap jangan menggunakan Aplikasi.",
      "section2Title": "2. Penggunaan Aplikasi",
      "section2Body": "Anda dapat menggunakan Aplikasi hanya untuk tujuan yang sah dan sesuai dengan Syarat ini. Anda setuju untuk tidak menggunakan Aplikasi untuk mengirimkan konten yang menyinggung, berbahaya, atau melanggar hak orang lain.",
      "section3Title": "3. Konten Buatan Pengguna",
      "section3Body": "Anda bertanggung jawab penuh atas pesan, teks, dan konten lain yang Anda buat dan bagikan melalui Aplikasi. E Greet tidak mendukung dan tidak bertanggung jawab atas konten buatan pengguna.",
      "section4Title": "4. Kekayaan Intelektual",
      "section4Body": "Semua elemen desain, karya seni bunga, animasi, dan perangkat lunak dalam Aplikasi adalah kekayaan intelektual E Greet. Anda tidak boleh mereproduksi, mendistribusikan, atau membuat karya turunan tanpa izin tertulis sebelumnya.",
      "section5Title": "5. Layanan Pihak Ketiga",
      "section5Body": "Aplikasi dapat terintegrasi dengan layanan pihak ketiga (seperti iTunes untuk pratinjau musik). Penggunaan Anda atas layanan tersebut tunduk pada syarat masing-masing. Kami tidak bertanggung jawab atas konten atau layanan pihak ketiga mana pun.",
      "section6Title": "6. Penafian Jaminan",
      "section6Body": "Aplikasi disediakan \"apa adanya\" tanpa jaminan apa pun. E Greet tidak menjamin bahwa Aplikasi akan bebas dari kesalahan atau tidak terganggu.",
      "section7Title": "7. Batasan Tanggung Jawab",
      "section7Body": "Sejauh yang diizinkan oleh hukum, E Greet tidak akan bertanggung jawab atas kerusakan tidak langsung, insidental, khusus, atau konsekuensial yang timbul dari penggunaan Anda atas Aplikasi.",
      "section8Title": "8. Perubahan pada Syarat",
      "section8Body": "Kami berhak mengubah Syarat ini kapan saja. Penggunaan berkelanjutan dari Aplikasi setelah perubahan diumumkan merupakan penerimaan atas Syarat baru.",
      "section9Title": "9. Kontak",
      "section9Body": "Jika Anda memiliki pertanyaan tentang Syarat ini, silakan hubungi kami di hello@egreet.in."
    },
