    "privacy": {
      "title": "Gizlilik Politikası",
      "badge": "Gizliliğin bizim için önemli",
      "lastUpdated": "Son güncelleme: Mayıs 2025",
      "section1Title": "Topladığımız Bilgiler",
      "section1Body": "Uygulamayı çalıştırmak için minimum düzeyde bilgi toplarız. Bunlar arasında şunlar yer alır:\n\n- Oluşturduğunuz buketler (Firebase Firestore'da saklanır)\n- Geri bildirim gönderirseniz isteğe bağlı e-posta adresiniz\n- Uygulamayı iyileştirmek için anonim kullanım analizleri\n\nUygulamayı kullanmak için bir hesap oluşturmanız veya kişisel bilgilerinizi vermeniz gerekmez.",
      "section2Title": "Bilgilerinizi Nasıl Kullanıyoruz",
      "section2Body": "Topladığımız bilgileri şu amaçlarla kullanırız:\n\n- Dijital buketlerinizi saklamak ve teslim etmek\n- Gönderdiğiniz geri bildirimlere yanıt vermek\n- Uygulama performansını ve özelliklerini geliştirmek\n- Kötüye kullanımı tespit etmek ve önlemek",
      "section3Title": "Veri Depolama ve Güvenlik",
      "section3Body": "Buket verileriniz Google Firebase'de güvenli bir şekilde saklanır. Endüstri standardı şifreleme ve güvenlik uygulamaları kullanıyoruz. Buket verilerini oluşturulduktan sonra 90 gün boyunca saklarız, sonrasında otomatik olarak silinebilirler.",
      "section4Title": "Üçüncü Taraf Hizmetleri",
      "section4Body": "Uygulama aşağıdaki üçüncü taraf hizmetlerini kullanır:\n\n- Google Firebase (veri depolama)\n- iTunes Search API (şarkı önizlemeleri - veri gönderilmez)\n- Sarvam AI (isteğe bağlı yapay zeka buket önerileri)\n\nHer hizmetin veri kullanımını düzenleyen kendi Gizlilik Politikası vardır.",
      "section5Title": "Çerezler ve İzleme",
      "section5Body": "Uygulama izleme çerezleri kullanmaz. Web üzerinde tercihlerinizi hatırlamak için yerel depolama kullanabiliriz. Reklam izleyicileri kullanmıyoruz veya verilerinizi üçüncü taraflara satmıyoruz.",
      "section6Title": "Çocukların Gizliliği",
      "section6Body": "Digi Bouquet, 13 yaşın altındaki çocuklara yönelik değildir. Çocuklardan bilerek kişisel bilgi toplamıyoruz. Çocuğunuzun bize kişisel bilgilerini verdiğine inanıyorsanız, lütfen bizimle iletişime geçin.",
      "section7Title": "Haklarınız",
      "section7Body": "Şu haklara sahipsiniz:\n\n- Hakkınızda tuttuğumuz verilere erişmek\n- Buket verilerinizin silinmesini talep etmek\n- Analizlerden çıkmak\n\nBu haklarınızı kullanmak için privacy@egreet.in adresinden bizimle iletişime geçin.",
      "section8Title": "Bu Politikadaki Değişiklikler",
      "section8Body": "Bu Gizlilik Politikasını zaman zaman güncelleyebiliriz. Önemli değişiklikleri size Uygulama üzerinden bildireceğiz. Güncellemelerden sonra kullanmaya devam etmeniz, revize edilen politikayı kabul ettiğiniz anlamına gelir.",
      "section9Title": "Bize Ulaşın",
      "section9Body": "Gizlilikle ilgili sorularınız veya veri talepleriniz için:\n\nE-posta: privacy@egreet.in\nWeb Sitesi: https://egreet.in"
    },
    "terms": {
      "title": "Şartlar ve Koşullar",
      "lastUpdated": "Son güncelleme: Mayıs 2025",
      "section1Title": "1. Şartların Kabulü",
      "section1Body": "Digi Bouquet'i (\"Uygulama\") indirerek, kurarak veya kullanarak bu Şartlar ve Koşullara tabi olmayı kabul etmiş olursunuz. Eğer kabul etmiyorsanız, lütfen Uygulamayı kullanmayın.",
      "section2Title": "2. Uygulamanın Kullanımı",
      "section2Body": "Uygulamayı yalnızca yasal amaçlar için ve bu Şartlara uygun olarak kullanabilirsiniz. Uygulamayı saldırgan, zararlı veya başkalarının haklarını ihlal eden herhangi bir içerik göndermek için kullanmamayı kabul edersiniz.",
      "section3Title": "3. Kullanıcı Tarafından Oluşturulan İçerik",
      "section3Body": "Uygulama aracılığıyla oluşturduğunuz ve paylaştığınız mesajlardan, metinlerden ve diğer içeriklerden tamamen siz sorumlusunuz. E Greet, kullanıcı tarafından oluşturulan hiçbir içeriği onaylamaz ve bunlardan sorumlu değildir.",
      "section4Title": "4. Fikri Mülkiyet",
      "section4Body": "Uygulamadaki tüm tasarım öğeleri, çiçek çizimleri, animasyonlar ve yazılımlar E Greet'in fikri mülkiyetidir. Önceden yazılı izin almadan bunları kopyalayamaz, dağıtamaz veya türev eserler oluşturamazsınız.",
      "section5Title": "5. Üçüncü Taraf Hizmetleri",
      "section5Body": "Uygulama üçüncü taraf hizmetleriyle entegre olabilir (müzik önizlemesi için iTunes gibi). Bu hizmetleri kullanımınız, kendi ilgili şartlarına tabidir. Üçüncü taraf içeriklerinden veya hizmetlerinden sorumlu değiliz.",
      "section6Title": "6. Garantilerin Reddi",
      "section6Body": "Uygulama \"olduğu gibi\", hiçbir garanti olmaksızın sunulmaktadır. E Greet, Uygulamanın hatasız veya kesintisiz olacağını garanti etmez.",
      "section7Title": "7. Sorumluluğun Sınırlandırılması",
      "section7Body": "Yasaların izin verdiği en geniş ölçüde, E Greet, Uygulamayı kullanımınızdan kaynaklanan herhangi bir dolaylı, tesadüfi, özel veya sonuç olarak ortaya çıkan zarardan sorumlu tutulamaz.",
      "section8Title": "8. Şartlarda Yapılacak Değişiklikler",
      "section8Body": "Bu Şartları herhangi bir zamanda değiştirme hakkımızı saklı tutarız. Değişiklikler yayınlandıktan sonra Uygulamayı kullanmaya devam etmeniz, yeni Şartları kabul ettiğiniz anlamına gelir.",
      "section9Title": "9. İletişim",
      "section9Body": "Bu Şartlarla ilgili sorularınız varsa, lütfen hello@egreet.in adresinden bizimle iletişime geçin."
    },
