    "privacy": {
      "title": "Privacybeleid",
      "badge": "Jouw privacy is belangrijk voor ons",
      "lastUpdated": "Laatst bijgewerkt: mei 2025",
      "section1Title": "Informatie die we verzamelen",
      "section1Body": "We verzamelen minimale informatie om de app te laten werken. Dit omvat:\n\n- Boeketten die je maakt (opgeslagen in Firebase Firestore)\n- Optioneel e-mailadres als je feedback stuurt\n- Anonieme gebruiksanalyses om de app te verbeteren\n\nJe hoeft geen account aan te maken of persoonlijke gegevens te verstrekken om de app te gebruiken.",
      "section2Title": "Hoe we je informatie gebruiken",
      "section2Body": "We gebruiken de verzamelde informatie om:\n\n- Je digitale boeketten op te slaan en af te leveren\n- Te reageren op je feedback\n- De prestaties en functies van de app te verbeteren\n- Misbruik op te sporen en te voorkomen",
      "section3Title": "Gegevensopslag & Beveiliging",
      "section3Body": "Je boeketgegevens worden veilig opgeslagen in Google Firebase. We gebruiken industriestandaard versleuteling en beveiligingspraktijken. We bewaren boeketgegevens 90 dagen na het aanmaken, waarna ze automatisch kunnen worden verwijderd.",
      "section4Title": "Diensten van derden",
      "section4Body": "De app gebruikt de volgende diensten van derden:\n\n- Google Firebase (gegevensopslag)\n- iTunes Search API (voorproefjes van liedjes - er worden geen gegevens verzonden)\n- Sarvam AI (optionele AI-boeket suggesties)\n\nElke dienst heeft zijn eigen privacybeleid voor gegevensgebruik.",
      "section5Title": "Cookies & Tracking",
      "section5Body": "De app gebruikt geen trackingcookies. Op het web kunnen we lokale opslag gebruiken om je voorkeuren te onthouden. We gebruiken geen reclametrackers en verkopen je gegevens niet aan derden.",
      "section6Title": "Privacy van kinderen",
      "section6Body": "Digi Bouquet is niet gericht op kinderen onder de 13 jaar. We verzamelen niet bewust persoonlijke gegevens van kinderen. Neem contact met ons op als je denkt dat een kind persoonlijke informatie met ons heeft gedeeld.",
      "section7Title": "Jouw rechten",
      "section7Body": "Je hebt het recht om:\n\n- Toegang te krijgen tot de gegevens die we over je hebben\n- Verwijdering van je boeketgegevens aan te vragen\n- Je af te melden voor analyses\n\nOm deze rechten uit te oefenen, kun je contact met ons opnemen via privacy@egreet.in.",
      "section8Title": "Wijzigingen in dit beleid",
      "section8Body": "We kunnen dit privacybeleid van tijd tot tijd bijwerken. Bij belangrijke wijzigingen laten we dit weten via de app. Blijf je de app gebruiken na de updates, dan ga je akkoord met het herziene beleid.",
      "section9Title": "Contact opnemen",
      "section9Body": "Voor vragen over privacy of gegevensverzoeken:\n\nE-mail: privacy@egreet.in\nWebsite: https://egreet.in"
    },
    "terms": {
      "title": "Algemene voorwaarden",
      "lastUpdated": "Laatst bijgewerkt: mei 2025",
      "section1Title": "1. Acceptatie van de voorwaarden",
      "section1Body": "Door Digi Bouquet (\"de app\") te downloaden, installeren of gebruiken, ga je akkoord met deze Algemene Voorwaarden. Als je niet akkoord gaat, gebruik de app dan niet.",
      "section2Title": "2. Gebruik van de app",
      "section2Body": "Je mag de app alleen gebruiken voor wettige doeleinden en in overeenstemming met deze voorwaarden. Je gaat ermee akkoord de app niet te gebruiken om inhoud te versturen die beledigend of schadelijk is, of die de rechten van anderen schendt.",
      "section3Title": "3. Door gebruikers gegenereerde inhoud",
      "section3Body": "Je bent als enige verantwoordelijk voor de berichten, tekst en andere inhoud die je maakt en deelt via de app. E Greet onderschrijft dit niet en is niet verantwoordelijk voor door gebruikers gegenereerde inhoud.",
      "section4Title": "4. Intellectueel eigendom",
      "section4Body": "Alle ontwerpelementen, bloemenkunst, animaties en software in de app zijn intellectueel eigendom van E Greet. Het is niet toegestaan om deze te reproduceren, verspreiden of afgeleide werken te maken zonder voorafgaande schriftelijke toestemming.",
      "section5Title": "5. Diensten van derden",
      "section5Body": "De app kan integreren met diensten van derden (zoals iTunes voor muziekvoorbeelden). Je gebruik van deze diensten is onderworpen aan hun respectievelijke voorwaarden. Wij zijn niet verantwoordelijk voor inhoud of diensten van derden.",
      "section6Title": "6. Afwijzing van garanties",
      "section6Body": "De app wordt \"zoals deze is\" geleverd zonder enige garantie. E Greet garandeert niet dat de app foutloos of ononderbroken zal werken.",
      "section7Title": "7. Beperking van aansprakelijkheid",
      "section7Body": "Voor zover wettelijk toegestaan, is E Greet niet aansprakelijk voor enige indirecte, incidentele, speciale of gevolgschade die voortvloeit uit je gebruik van de app.",
      "section8Title": "8. Wijzigingen van de voorwaarden",
      "section8Body": "We behouden ons het recht voor om deze voorwaarden te allen tijde te wijzigen. Blijf je de app gebruiken nadat wijzigingen zijn geplaatst, dan accepteer je de nieuwe voorwaarden.",
      "section9Title": "9. Contact",
      "section9Body": "Als je vragen hebt over deze voorwaarden, neem dan contact met ons op via hello@egreet.in."
    },
