    "privacy": {
      "title": "Polityka prywatności",
      "badge": "Twoja prywatność jest dla nas ważna",
      "lastUpdated": "Ostatnia aktualizacja: Maj 2025",
      "section1Title": "1. Informacje, które zbieramy",
      "section1Body": "Zbieramy minimalne informacje niezbędne do działania Aplikacji. Obejmują one:\n\n- Bukiety, które tworzysz (przechowywane w Firebase Firestore)\n- Opcjonalny e-mail, jeśli prześlesz opinię\n- Anonimowe statystyki użytkowania w celu ulepszania Aplikacji\n\nNie wymagamy od Ciebie tworzenia konta ani podawania danych osobowych do korzystania z Aplikacji.",
      "section2Title": "2. Jak wykorzystujemy Twoje informacje",
      "section2Body": "Informacje te wykorzystujemy do:\n\n- Przechowywania i dostarczania Twoich cyfrowych bukietów\n- Odpowiadania na Twoje opinie\n- Poprawy wydajności i funkcji aplikacji\n- Wykrywania i zapobiegania nadużyciom",
      "section3Title": "3. Przechowywanie i bezpieczeństwo danych",
      "section3Body": "Dane Twojego bukietu są bezpiecznie przechowywane w Google Firebase. Stosujemy standardowe w branży metody szyfrowania i zasady bezpieczeństwa. Przechowujemy dane bukietów przez 90 dni od utworzenia, po czym mogą zostać automatycznie usunięte.",
      "section4Title": "4. Usługi podmiotów trzecich",
      "section4Body": "Aplikacja korzysta z następujących usług stron trzecich:\n\n- Google Firebase (przechowywanie danych)\n- iTunes Search API (podgląd piosenek - nie są wysyłane żadne dane)\n- Sarvam AI (opcjonalne sugestie bukietów AI)\n\nKażda usługa ma własną Politykę Prywatności regulującą wykorzystanie danych.",
      "section5Title": "5. Ciasteczka i śledzenie",
      "section5Body": "Aplikacja nie używa śledzących plików cookie. W wersji przeglądarkowej możemy korzystać z pamięci lokalnej (local storage) w celu zapamiętywania Twoich preferencji. Nie używamy trackerów reklamowych i nie sprzedajemy Twoich danych.",
      "section6Title": "6. Prywatność dzieci",
      "section6Body": "Digi Bouquet nie jest przeznaczone dla dzieci poniżej 13. roku życia. Świadomie nie gromadzimy danych osobowych od dzieci. Jeśli uważasz, że dziecko przekazało nam dane osobowe, skontaktuj się z nami.",
      "section7Title": "7. Twoje prawa",
      "section7Body": "Masz prawo do:\n\n- Dostępu do danych, które przechowujemy na Twój temat\n- Żądania usunięcia danych Twojego bukietu\n- Rezygnacji ze zbierania analityki\n\nAby skorzystać z tych praw, napisz do nas: privacy@egreet.in.",
      "section8Title": "8. Zmiany w tej polityce",
      "section8Body": "Możemy od czasu do czasu aktualizować tę Politykę Prywatności. O istotnych zmianach powiadomimy Cię przez Aplikację. Dalsze korzystanie z aplikacji po zmianach oznacza akceptację zrewidowanej polityki.",
      "section9Title": "9. Kontakt",
      "section9Body": "W sprawach prywatności i zapytań o dane:\n\nE-mail: privacy@egreet.in\nStrona WWW: https://egreet.in"
    },
    "terms": {
      "title": "Regulamin",
      "lastUpdated": "Ostatnia aktualizacja: Maj 2025",
      "section1Title": "1. Akceptacja Warunków",
      "section1Body": "Pobierając, instalując lub korzystając z Digi Bouquet („Aplikacja”), zgadzasz się przestrzegać niniejszego Regulaminu. Jeśli się nie zgadzasz, nie korzystaj z Aplikacji.",
      "section2Title": "2. Korzystanie z Aplikacji",
      "section2Body": "Z Aplikacji można korzystać wyłącznie w celach zgodnych z prawem i niniejszym Regulaminem. Zgadzasz się nie używać Aplikacji do wysyłania treści obraźliwych, szkodliwych lub naruszających prawa innych.",
      "section3Title": "3. Treści Generowane przez Użytkownika",
      "section3Body": "Ponosisz wyłączną odpowiedzialność za wiadomości, tekst i inne treści, które tworzysz i udostępniasz za pośrednictwem Aplikacji. E Greet nie popiera i nie ponosi odpowiedzialności za treści generowane przez użytkowników.",
      "section4Title": "4. Własność Intelektualna",
      "section4Body": "Wszystkie elementy graficzne, grafiki kwiatów, animacje i oprogramowanie w Aplikacji stanowią własność intelektualną E Greet. Nie wolno ich reprodukować, rozpowszechniać ani tworzyć dzieł pochodnych bez uprzedniej pisemnej zgody.",
      "section5Title": "5. Usługi Stron Trzecich",
      "section5Body": "Aplikacja może integrować się z usługami stron trzecich (np. iTunes w celu podglądu muzyki). Korzystanie z nich podlega odpowiednim warunkom tych usług. Nie odpowiadamy za treści ani usługi stron trzecich.",
      "section6Title": "6. Wyłączenie Gwarancji",
      "section6Body": "Aplikacja jest dostarczana „taka jaka jest” bez jakichkolwiek gwarancji. E Greet nie gwarantuje, że Aplikacja będzie wolna od błędów ani że jej działanie będzie nieprzerwane.",
      "section7Title": "7. Ograniczenie Odpowiedzialności",
      "section7Body": "W najszerszym zakresie dozwolonym przez prawo, E Greet nie ponosi odpowiedzialności za jakiekolwiek pośrednie, przypadkowe, szczególne lub wtórne szkody wynikające z korzystania z Aplikacji.",
      "section8Title": "8. Zmiany Regulaminu",
      "section8Body": "Zastrzegamy sobie prawo do modyfikacji tego Regulaminu w dowolnym momencie. Dalsze korzystanie z Aplikacji po publikacji zmian oznacza ich akceptację.",
      "section9Title": "9. Kontakt",
      "section9Body": "Jeśli masz pytania dotyczące Regulaminu, skontaktuj się z nami na adres hello@egreet.in."
    },
