      "help2_1": "தனிப்பயன் பயன்முறையை இயக்கி பூக்களை நகர்த்த இழுக்கவும்",
      "help2_2": "அளவை மாற்ற அல்லது சுழற்ற கட்டுப்பாடுகளைப் பயன்படுத்தவும்",
      "help2_3": "நிலைகளை சீரற்ற முறையில் மாற்ற 'கலைத்துப்போடு' என்பதைத் தட்டவும்",
      "help2_4": "பின்னணியை மாற்ற BG என்பதைத் தட்டவும்",
