      "missionTitle": "எங்கள் நோக்கம்",
      "missionBody": "Digi Bouquet நீங்கள் அக்கறை கொள்ளும் நபர்களுக்கு அழகான, தனிப்பயனாக்கப்பட்ட டிஜிட்டல் பூங்கொத்துகளை அனுப்புவதை எளிதாக்குகிறது. இது பிறந்தநாளோ, திருமண நாளோ, அல்லது சாதாரணமாகவோ இருக்கட்டும் — ஒருபோதும் வாடாத பூக்களால் உங்கள் உணர்வுகளை வெளிப்படுத்துங்கள்.",
