      "startingPoint": "தொடக்கப் புள்ளி",
      "startsAt": "{time} வினாடிகளில் தொடங்குகிறது",
      "quickSeek": "விரைவான தேடல்:",
      "selectButton": "தேர்ந்தெடு",
      "addSongTitle": "உங்கள் பூங்கொத்துக்கு ஒரு பாடலைச் சேர்க்கவும்",
