    "privacy": {
      "title": "Integritetspolicy",
      "badge": "Din integritet är viktig för oss",
      "lastUpdated": "Senast uppdaterad: Maj 2025",
      "section1Title": "Information vi samlar in",
      "section1Body": "Vi samlar in minimalt med information för att driva appen. Detta inkluderar:\n\n- Buketter du skapar (sparas i Firebase Firestore)\n- Valfri mejladress om du skickar feedback\n- Anonym användarstatistik för att förbättra appen\n\nVi kräver inte att du skapar ett konto eller anger personuppgifter för att använda appen.",
      "section2Title": "Hur vi använder din information",
      "section2Body": "Vi använder informationen vi samlar in för att:\n\n- Spara och leverera dina digitala buketter\n- Svara på feedback du skickar\n- Förbättra appens prestanda och funktioner\n- Upptäcka och förhindra missbruk",
      "section3Title": "Datalagring och säkerhet",
      "section3Body": "Din bukettdata sparas säkert i Google Firebase. Vi använder branschstandard för kryptering och säkerhet. Vi behåller bukettdata i 90 dagar efter skapandet, därefter kan den raderas automatiskt.",
      "section4Title": "Tredjepartstjänster",
      "section4Body": "Appen använder följande tredjepartstjänster:\n\n- Google Firebase (datalagring)\n- iTunes Search API (låtförhandsvisningar - ingen data skickas)\n- Sarvam AI (valfria AI-förslag för buketter)\n\nVarje tjänst har sin egen integritetspolicy som styr hur data används.",
      "section5Title": "Cookies och spårning",
      "section5Body": "Appen använder inte spårningscookies. På webben kan vi använda lokal lagring för att komma ihåg dina val. Vi använder inga annonsspårare och säljer inte din data till tredje part.",
      "section6Title": "Barns integritet",
      "section6Body": "Digi Bouquet riktar sig inte till barn under 13 år. Vi samlar inte medvetet in personuppgifter från barn. Kontakta oss om du tror att ett barn har gett oss personuppgifter.",
      "section7Title": "Dina rättigheter",
      "section7Body": "Du har rätt att:\n\n- Begära tillgång till den data vi har om dig\n- Begära radering av din bukettdata\n- Välja bort statistikinsamling\n\nKontakta oss på privacy@egreet.in för att utöva dessa rättigheter.",
      "section8Title": "Ändringar i denna policy",
      "section8Body": "Vi kan komma att uppdatera denna integritetspolicy från tid till annan. Vi meddelar dig om viktiga ändringar via appen. Fortsatt användning efter ändringar innebär att du accepterar den reviderade policyn.",
      "section9Title": "Kontakta oss",
      "section9Body": "För frågor om integritet eller data:\n\nMejl: privacy@egreet.in\nWebbplats: https://egreet.in"
    },
    "terms": {
      "title": "Användarvillkor",
      "lastUpdated": "Senast uppdaterad: Maj 2025",
      "section1Title": "1. Godkännande av villkoren",
      "section1Body": "Genom att ladda ner, installera eller använda Digi Bouquet (\"Appen\") godkänner du dessa användarvillkor. Om du inte samtycker ber vi dig att inte använda appen.",
      "section2Title": "2. Användning av appen",
      "section2Body": "Du får endast använda appen för lagliga ändamål och i enlighet med dessa villkor. Du får inte använda appen för att skicka innehåll som är stötande, skadligt eller kränker andras rättigheter.",
      "section3Title": "3. Användargenererat innehåll",
      "section3Body": "Du är ensam ansvarig för de meddelanden, texter och annat innehåll du skapar och delar via appen. E Greet stöder inte och ansvarar inte för något användargenererat innehåll.",
      "section4Title": "4. Immaterialrätt",
      "section4Body": "Alla designelement, blomillustrationer, animeringar och mjukvara i appen tillhör E Greet. Du får inte kopiera, distribuera eller skapa härledda verk utan föregående skriftligt tillstånd.",
      "section5Title": "5. Tredjepartstjänster",
      "section5Body": "Appen kan integreras med tredjepartstjänster (som iTunes för förhandsvisning av musik). Din användning av dessa tjänster styrs av deras respektive villkor. Vi ansvarar inte för innehåll eller tjänster från tredje part.",
      "section6Title": "6. Ansvarsfriskrivning",
      "section6Body": "Appen tillhandahålls i \"befintligt skick\" utan några garantier. E Greet garanterar inte att appen kommer att vara felfri eller utan avbrott.",
      "section7Title": "7. Ansvarsbegränsning",
      "section7Body": "I den utsträckning lagen tillåter ska E Greet inte hållas ansvarigt för några indirekta, tillfälliga, särskilda eller följdskador som uppstår på grund av din användning av appen.",
      "section8Title": "8. Ändringar av villkoren",
      "section8Body": "Vi förbehåller oss rätten att ändra dessa villkor när som helst. Fortsatt användning av appen efter att ändringar publicerats innebär ett godkännande av de nya villkoren.",
      "section9Title": "9. Kontakt",
      "section9Body": "Om du har frågor om dessa villkor, vänligen kontakta oss på hello@egreet.in."
    },
